def get_svg(name: str, size: int = 24, color: str = "#0B57D0", extra_style: str = "") -> str:
    """Trả về chuỗi SVG vector inline chuẩn hóa theo kích thước và mã màu Material Design 3."""
    path = SVG_PATHS.get(name, SVG_PATHS["dashboard"])
    style_attr = f'style="vertical-align: middle; display: inline-block; {extra_style}"'
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="{size}" height="{size}" fill="{color}" {style_attr}>{path}</svg>'


def svg_icon_header(name: str, text: str, size: int = 28, color: str = "#0B57D0") -> str:
    """Tạo tiêu đề kết hợp icon SVG vector và văn bản chuẩn Material Design 3."""
    svg = get_svg(name, size=size, color=color, extra_style="margin-right: 8px; margin-bottom: 3px;")
    return f'<div style="display: flex; align-items: center; gap: 8px;">{svg}<span style="font-weight: 700;">{text}</span></div>'
